   192→  private execHotPath(inst: Inst, program: Inst[]): void {
   193→    const op = inst.op;
   194→
   195→    // PUSH: most common operation
   196→    if (op === Op.PUSH) {
   197→      this.guardStack();
   198→      this.stack.push(inst.arg as number);
   199→      this.pc++;
   200→      return;
   201→    }
   202→
   203→    // POP
   204→    if (op === Op.POP) {
   205→      this.need(1);
   206→      this.stack.pop();
   207→      this.pc++;
   208→      return;
   209→    }
