   211→    // Binary arithmetic (hot operations in math-heavy code)
   212→    if (op === Op.ADD) {
   213→      this.binop((a, b) => a + b);
   214→      return;
   215→    }
   216→    if (op === Op.SUB) {
   217→      this.binop((a, b) => a - b);
   218→      return;
   219→    }
   220→    if (op === Op.MUL) {
   221→      this.binop((a, b) => a * b);
   222→      return;
   223→    }
   224→    if (op === Op.DIV) {
   225→      this.need(2);
   226→      if (this.stack[this.stack.length - 1] === 0) {
   227→        throw new Error('div_zero');
   228→      }
   229→      this.binop((a, b) => a / b);
   230→      return;
   231→    }
   232→
   233→    // LOAD: common variable access
   234→    if (op === Op.LOAD) {
   235→      const varName = inst.arg as string;
   236→      const v = this.vars.get(varName);
   237→      if (process.env.DEBUG_STORE) {
   238→        console.log(`[DEBUG LOAD] Getting vars["${varName}"]`);
   239→        console.log(`[DEBUG LOAD] vars keys available:`, Array.from(this.vars.keys()));
   240→        console.log(`[DEBUG LOAD] Result:`, v);
   241→      }
   242→      if (v === undefined) throw new Error('undef_var:' + varName);
   243→      this.guardStack();
   244→      this.stack.push(v);
   245→      this.pc++;
   246→      return;
   247→    }
   248→
   249→    // STORE: common variable assignment
   250→    if (op === Op.STORE) {
   251→      this.need(1);
   252→      const varName = inst.arg as string;
   253→      const value = this.stack.pop()!;
   254→      if (process.env.DEBUG_STORE) {
   255→        console.log(`[DEBUG STORE] Setting vars["${varName}"] = ${JSON.stringify(value)}`);
   256→        console.log(`[DEBUG STORE] vars keys before:`, Array.from(this.vars.keys()));
   257→      }
   258→      this.vars.set(varName, value);
   259→      if (process.env.DEBUG_STORE) {
   260→        console.log(`[DEBUG STORE] vars keys after:`, Array.from(this.vars.keys()));
   261→        console.log(`[DEBUG STORE] vars["${varName}"] =`, this.vars.get(varName));
   262→      }
   263→      this.pc++;
   264→      return;
   265→    }
   266→
   267→    // Fallback to main exec for other hot path ops
   268→    this.exec(inst, program);
   269→  }
