   276→      case Op.PUSH:
   277→        this.guardStack();
   278→        this.stack.push(arg as number);
   279→        this.pc++;
   280→        break;
   281→
   282→      case Op.PUSH_FLOAT:
   283→        this.guardStack();
   284→        this.stack.push(arg as number);  // JavaScript number is 64-bit float
   285→        this.pc++;
   286→        break;
   287→
   288→      case Op.POP:
   289→        this.need(1);
   290→        this.stack.pop();
   291→        this.pc++;
   292→        break;
   293→
   294→      case Op.DUP:
   295→        this.need(1);
   296→        this.guardStack();
   297→        this.stack.push(this.stack[this.stack.length - 1]);
   298→        this.pc++;
   299→        break;
   300→
   301→      // ── Arithmetic ──
   302→      case Op.ADD: this.binop((a, b) => a + b); break;
   303→      case Op.SUB: this.binop((a, b) => a - b); break;
   304→      case Op.MUL: this.binop((a, b) => a * b); break;
   305→      case Op.DIV:
   306→        this.need(2);
   307→        if (this.stack[this.stack.length - 1] === 0) {
   308→          throw new Error('div_zero');
   309→        }
   310→        this.binop((a, b) => a / b);
   311→        break;
   312→      case Op.MOD: this.binop((a, b) => a % b); break;
   313→      case Op.NEG:
   314→        this.need(1);
   315→        this.stack[this.stack.length - 1] = -this.stack[this.stack.length - 1];
   316→        this.pc++;
   317→        break;
   318→
   319→      // ── Float Arithmetic (Phase 3 Level 3) ──
   320→      case Op.FADD: this.binop((a, b) => a + b); break;  // Same as ADD (JavaScript number is f64)
   321→      case Op.FSUB: this.binop((a, b) => a - b); break;
   322→      case Op.FMUL: this.binop((a, b) => a * b); break;
   323→      case Op.FDIV:
   324→        this.need(2);
   325→        if (this.stack[this.stack.length - 1] === 0) {
   326→          throw new Error('fdiv_zero');
   327→        }
   328→        this.binop((a, b) => a / b);
   329→        break;
   330→
   331→      // ── Float Conversions ──
   332→      case Op.F2I:  // float → int
   333→        this.need(1);
   334→        this.stack[this.stack.length - 1] = Math.trunc(this.stack[this.stack.length - 1] as number);
   335→        this.pc++;
   336→        break;
   337→      case Op.I2F:  // int → float (no-op in JavaScript, but semantically correct)
   338→        this.need(1);
   339→        this.stack[this.stack.length - 1] = Number(this.stack[this.stack.length - 1] as number);
   340→        this.pc++;
   341→        break;
   342→
   343→      // ── Comparison ──
   344→      case Op.EQ:  this.binop((a, b) => a === b ? 1 : 0); break;
   345→      case Op.NEQ: this.binop((a, b) => a !== b ? 1 : 0); break;
   346→      case Op.LT:  this.binop((a, b) => a < b ? 1 : 0); break;
   347→      case Op.GT:  this.binop((a, b) => a > b ? 1 : 0); break;
   348→      case Op.LTE: this.binop((a, b) => a <= b ? 1 : 0); break;
   349→      case Op.GTE: this.binop((a, b) => a >= b ? 1 : 0); break;
   350→
   351→      // ── Logic ──
   352→      case Op.AND: this.binop((a, b) => (a && b) ? 1 : 0); break;
   353→      case Op.OR:  this.binop((a, b) => (a || b) ? 1 : 0); break;
   354→      case Op.NOT:
