   445→        this.stack.push(value);
   446→        this.pc++;
   447→        break;
   448→      }
   449→
   450→      case Op.ARR_SET: {
   451→        this.need(2);
   452→        const container = this.vars.get(arg as string);
   453→        if (!container || typeof container !== 'object') throw new Error('not_indexable:' + arg);
   454→        const val = this.stack.pop();
   455→        const key = this.stack.pop();
   456→
   457→        // Handle both arrays and objects
