   459→          // Convert float indices to int (truncate)
   460→          const idx = Math.floor(key as number);
   461→          if (idx < 0 || idx >= container.length) throw new Error('oob:' + idx);
   462→          container[idx] = val;
   463→        } else {
   464→          // Object: use string key
   465→          const strKey = String(key);
   466→          (container as any)[strKey] = val;
   467→        }
