   469→        this.pc++;
   470→        break;
   471→      }
   472→
   473→      case Op.ARR_LEN: {
   474→        let value;
   475→        if (arg) {
   476→          // Variable-based: value = this.vars.get(arg)
   477→          value = this.vars.get(arg as string);
   478→        } else {
   479→          // Stack-based: pop value from stack
   480→          this.need(1);
   481→          value = this.stack.pop();
   482→        }
   483→
   484→        // Support both arrays and strings
   485→        if (value === null || value === undefined) {
