   487→        }
   488→
   489→        // Get length property - works for arrays and strings
   490→        const len = (value as any).length;
   491→        if (typeof len !== 'number') {
   492→          throw new Error('no_length_property');
   493→        }
   494→
   495→        this.guardStack();
   496→        this.stack.push(len);
   497→        this.pc++;
   498→        break;
   499→      }
   500→
   501→      // ── Object Operations ──────────────────
   502→      case Op.OBJ_NEW:
