   513→        const key = argStr.substring(colonIdx + 1);
   514→        const obj = this.vars.get(varName);
   515→        if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
   516→          throw new Error('not_object:' + varName);
   517→        }
   518→        const val = this.stack.pop();
