  1057→        // arg: string → push to stack
  1058→        this.guardStack();
  1059→        this.stack.push(arg as string);
  1060→        this.pc++;
  1061→        break;
  1062→
  1063→      case Op.STR_LEN: {
  1064→        // stack: [str] → [length]
  1065→        this.need(1);
  1066→        const str = this.stack[this.stack.length - 1];
  1067→        if (typeof str !== 'string') throw new Error('not_string');
  1068→        this.stack[this.stack.length - 1] = str.length;
  1069→        this.pc++;
  1070→        break;
  1071→      }
  1072→
  1073→      case Op.STR_AT: {
  1074→        // stack: [str, index] → [char]
  1075→        this.need(2);
  1076→        const idx = this.stack.pop() as number;
  1077→        const str = this.stack.pop() as string;
  1078→        if (typeof str !== 'string') throw new Error('not_string');
  1079→        this.guardStack();
  1080→        this.stack.push(str[Math.floor(idx)] || '');
  1081→        this.pc++;
  1082→        break;
  1083→      }
  1084→
  1085→      case Op.STR_SUB: {
  1086→        // stack: [str, start, end] → [substr]
  1087→        this.need(3);
  1088→        const end = this.stack.pop() as number;
  1089→        const start = this.stack.pop() as number;
  1090→        const str = this.stack.pop() as string;
  1091→        if (typeof str !== 'string') throw new Error('not_string');
  1092→        this.guardStack();
  1093→        this.stack.push(str.substring(Math.floor(start), Math.floor(end)));
  1094→        this.pc++;
  1095→        break;
  1096→      }
  1097→
  1098→      case Op.STR_CONCAT: {
  1099→        // stack: [str1, str2] → [str1+str2]
  1100→        this.need(2);
  1101→        const str2 = this.stack.pop();
  1102→        const str1 = this.stack.pop();
  1103→        if (typeof str1 !== 'string' || typeof str2 !== 'string') {
  1104→          throw new Error('not_string');
  1105→        }
  1106→        this.guardStack();
  1107→        this.stack.push(str1 + str2);
  1108→        this.pc++;
  1109→        break;
  1110→      }
  1111→
  1112→      case Op.STR_EQ: {
  1113→        // stack: [str1, str2] → [bool]
  1114→        this.need(2);
  1115→        const str2 = this.stack.pop();
  1116→        const str1 = this.stack.pop();
  1117→        if (typeof str1 !== 'string' || typeof str2 !== 'string') {
  1118→          throw new Error('not_string');
  1119→        }
  1120→        this.guardStack();
  1121→        this.stack.push(str1 === str2 ? 1 : 0);
  1122→        this.pc++;
  1123→        break;
  1124→      }
  1125→
  1126→      case Op.STR_NEQ: {
  1127→        // stack: [str1, str2] → [bool]
  1128→        this.need(2);
  1129→        const str2 = this.stack.pop();
  1130→        const str1 = this.stack.pop();
  1131→        if (typeof str1 !== 'string' || typeof str2 !== 'string') {
  1132→          throw new Error('not_string');
  1133→        }
  1134→        this.guardStack();
  1135→        this.stack.push(str1 !== str2 ? 1 : 0);
  1136→        this.pc++;
  1137→        break;
  1138→      }
  1139→
  1140→      case Op.CHAR_NEW:
  1141→        // arg: char → push to stack
  1142→        this.guardStack();
  1143→        this.stack.push((arg as string).charAt(0) || '');
  1144→        this.pc++;
  1145→        break;
  1146→
  1147→      case Op.CHAR_CODE: {
  1148→        // stack: [char] → [code]
  1149→        this.need(1);
  1150→        const char = this.stack[this.stack.length - 1];
  1151→        if (typeof char !== 'string' || char.length === 0) {
  1152→          throw new Error('not_char');
  1153→        }
  1154→        this.stack[this.stack.length - 1] = char.charCodeAt(0);
  1155→        this.pc++;
  1156→        break;
  1157→      }
  1158→
  1159→      case Op.CHAR_FROM: {
  1160→        // stack: [code] → [char]
  1161→        this.need(1);
  1162→        const code = this.stack[this.stack.length - 1] as number;
  1163→        this.stack[this.stack.length - 1] = String.fromCharCode(Math.floor(code));
  1164→        this.pc++;
  1165→        break;
  1166→      }
  1167→
  1168→      // ── Exception Handling (Phase I) ──
  1169→      case Op.TRY_START: {
  1170→        // arg: catch block offset
  1171→        // Push try context to tryStack
  1172→        this.tryStack.push({
  1173→          catchOffset: arg as number,
  1174→          errorVar: '_error'  // default error variable name
  1175→        });
  1176→        this.pc++;
  1177→        break;
  1178→      }
  1179→
  1180→      case Op.CATCH_START: {
  1181→        // arg: error variable name
  1182→        // Store the error message in the specified variable
  1183→        if (this.stack.length > 0) {
  1184→          const errorValue = this.stack[this.stack.length - 1];
  1185→          this.vars.set(arg as string, errorValue);
  1186→        }
  1187→        this.pc++;
  1188→        break;
  1189→      }
  1190→
  1191→      case Op.CATCH_END: {
  1192→        // Pop try context from tryStack
  1193→        if (this.tryStack.length > 0) {
  1194→          this.tryStack.pop();
  1195→        }
  1196→        this.pc++;
  1197→        break;
  1198→      }
  1199→
  1200→      case Op.THROW: {
  1201→        // stack: [error_message] → throw error
  1202→        this.need(1);
  1203→        const errorMsg = this.stack.pop();
  1204→
  1205→        // Look for an active try block
  1206→        if (this.tryStack.length > 0) {
  1207→          // Push error to stack for catch block
  1208→          this.guardStack();
  1209→          this.stack.push(errorMsg!);
  1210→          // Jump to catch block
  1211→          const tryContext = this.tryStack[this.tryStack.length - 1];
  1212→          this.pc = tryContext.catchOffset;
  1213→        } else {
  1214→          // No try block, throw JavaScript error
  1215→          throw new Error('uncaught_exception:' + String(errorMsg));
  1216→        }
  1217→        break;
  1218→      }
  1219→
  1220→      // ── Lambda / Closure Metadata (파서가 클로저 객체로 처리, VM에서 skip) ──
  1221→      case Op.LAMBDA_NEW:
  1222→      case Op.LAMBDA_CAPTURE:
  1223→      case Op.LAMBDA_SET_BODY:
  1224→      case Op.FUNC_DEF:
  1225→      case Op.COMMENT:
  1226→        this.pc++;
  1227→        break;
  1228→
  1229→      // ── Debug ──
  1230→      case Op.DUMP:
  1231→        // AI reads this programmatically, no console.log
  1232→        this.pc++;
  1233→        break;
  1234→
  1235→      default:
  1236→        throw new Error('unknown_op:' + op);
  1237→    }
  1238→  }
