  1240→  private binop(fn: (a: number, b: number) => number): void {
  1241→    this.need(2);
  1242→    const b = this.stack.pop() as number;
  1243→    const a = this.stack.pop() as number;
  1244→    this.guardStack();
  1245→    this.stack.push(fn(a, b));
  1246→    this.pc++;
  1247→  }
  1248→
  1249→  private need(n: number): void {
  1250→    if (this.stack.length < n) {
  1251→      throw new Error('stack_underflow:need=' + n + ',have=' + this.stack.length);
  1252→    }
  1253→  }
  1254→
  1255→  private guardStack(): void {
  1256→    if (this.stack.length >= MAX_STACK) {
  1257→      throw new Error('stack_overflow');
  1258→    }
  1259→  }
  1260→
  1261→  private getArr(name: string): number[] {
  1262→    const arr = this.vars.get(name);
  1263→    if (!Array.isArray(arr)) throw new Error('not_array:' + name);
  1264→    return arr;
  1265→  }
  1266→
  1267→  private runSub(subProgram: Inst[]): VMResult {
  1268→    const savedPc = this.pc;
  1269→    this.pc = 0;
  1270→    while (this.pc < subProgram.length) {
  1271→      if (this.cycles++ > 100_000) {
  1272→        const result = this.fail(Op.HALT, 1, 'cycle_limit');
  1273→        this.pc = savedPc;
  1274→        return result;
  1275→      }
  1276→      const inst = subProgram[this.pc];
  1277→      if (inst.op === Op.RET || inst.op === Op.HALT) {
  1278→        this.pc = savedPc;
  1279→        break;
  1280→      }
  1281→      this.exec(inst, subProgram);
  1282→    }
  1283→    this.pc = savedPc;
  1284→    return { ok: true, value: undefined, cycles: this.cycles, ms: 0 };
  1285→  }
  1286→
  1287→  /**
  1288→   * Phase 19: Run a program IR and return its result
  1289→   * Used for function body execution
  1290→   */
  1291→  private runProgram(program: Inst[]): VMResult {
  1292→    const savedPc = this.pc;
  1293→    const savedStack = this.stack;  // Save reference, not copy
  1294→    this.stack = [];  // Isolated stack for this sub-program
  1295→    this.pc = 0;
  1296→
  1297→    try {
  1298→      while (this.pc < program.length) {
  1299→        if (this.cycles++ > 100_000) {
  1300→          this.pc = savedPc;
  1301→          this.stack = savedStack;  // Restore stack before returning
  1302→          return this.fail(Op.HALT, 1, 'cycle_limit');
  1303→        }
  1304→        const inst = program[this.pc];
  1305→        if (inst.op === Op.RET || inst.op === Op.HALT) {
  1306→          break;
  1307→        }
  1308→        this.exec(inst, program);
  1309→      }
  1310→
  1311→      // Get return value from stack
  1312→      const value = this.stack.length > 0 ? this.stack[this.stack.length - 1] : undefined;
  1313→      this.pc = savedPc;
  1314→      this.stack = savedStack;  // Restore stack before returning (was missing in success path!)
  1315→      return { ok: true, value, cycles: this.cycles, ms: 0 };
  1316→    } catch (e: unknown) {
  1317→      this.pc = savedPc;
  1318→      this.stack = savedStack;  // Restore stack on error
  1319→      const msg = e instanceof Error ? e.message : String(e);
  1320→      return this.fail(Op.HALT, 99, msg);
  1321→    }
  1322→  }
