  1324→  /**
  1325→   * Phase 26: Execute user-defined function with arguments (for higher-order functions)
  1326→   * Used by map/filter/reduce callbacks
  1327→   */
  1328→  public callUserFunction(functionName: string, args: any[]): any {
  1329→    if (!this.functionRegistry || !this.functionRegistry.exists(functionName)) {
  1330→      throw new Error(`Function not found: ${functionName}`);
  1331→    }
  1332→
  1333→    const fn = this.functionRegistry.lookup(functionName);
  1334→    if (!fn) throw new Error('function_lookup_failed:' + functionName);
  1335→
  1336→    // Save current state
  1337→    const savedVars = this.vars;
  1338→    this.vars = new Map(savedVars);
  1339→
  1340→    // Bind parameters
  1341→    for (let i = 0; i < fn.params.length; i++) {
  1342→      this.vars.set(fn.params[i], args[i]);
  1343→    }
  1344→
  1345→    // Execute function body
  1346→    const gen = new IRGenerator();
  1347→    const bodyNode = fn.body || { type: 'block', body: [] };
  1348→    const bodyIR = gen.generateIR(bodyNode);
  1349→
  1350→    let returnValue: any = undefined;
  1351→    const result = this.runProgram(bodyIR);
  1352→    returnValue = result.value;
  1353→
  1354→    // Restore caller's variables
  1355→    this.vars = savedVars;
  1356→
  1357→    return returnValue;
  1358→  }
  1359→
  1360→  /**
  1361→   * Phase 7-D: Execute closure (lambda/anonymous function) with arguments
  1362→   * Closures can be passed as function values to higher-order functions like map/filter/reduce
  1363→   */
  1364→  public callClosure(closure: any, args: any[]): any {
  1365→    // Validate closure structure
  1366→    if (!closure || closure.type !== 'lambda') {
  1367→      throw new Error('invalid_closure:expected_lambda_object');
  1368→    }
  1369→
  1370→    // Save current state and create new scope
  1371→    const savedVars = this.vars;
  1372→    this.vars = new Map(savedVars);
  1373→
  1374→    // If closure has captured variables, restore them
  1375→    if (closure.capturedVars && Array.isArray(closure.capturedVars)) {
  1376→      for (const capturedVar of closure.capturedVars) {
  1377→        if (capturedVar.name && savedVars.has(capturedVar.name)) {
  1378→          this.vars.set(capturedVar.name, savedVars.get(capturedVar.name));
  1379→        }
  1380→      }
  1381→    }
  1382→
  1383→    // Bind closure parameters
  1384→    const paramNames = closure.params || [];
  1385→    for (let i = 0; i < paramNames.length && i < args.length; i++) {
  1386→      const paramName = typeof paramNames[i] === 'string' ? paramNames[i] : paramNames[i].name;
  1387→      this.vars.set(paramName, args[i]);
  1388→    }
  1389→
  1390→    // Execute closure body
  1391→    const gen = new IRGenerator();
  1392→    const bodyNode = closure.body;
  1393→    if (!bodyNode) {
  1394→      throw new Error('closure_body_undefined');
  1395→    }
  1396→
  1397→    const bodyIR = gen.generateIR(bodyNode);
  1398→    let returnValue: any = undefined;
  1399→
  1400→    try {
  1401→      const result = this.runProgram(bodyIR);
  1402→      returnValue = result.value;
  1403→    } catch (e) {
  1404→      // Restore variables before throwing
  1405→      this.vars = savedVars;
  1406→      throw e;
  1407→    }
  1408→
  1409→    // Restore caller's variables
  1410→    this.vars = savedVars;
  1411→
  1412→    return returnValue;
  1413→  }
