  1422→  private fail(op: Op, code: number, detail: string, ms?: number): VMResult {
  1423→    return {
  1424→      ok: false,
  1425→      cycles: this.cycles,
  1426→      ms: ms ?? 0,
  1427→      error: {
  1428→        code,
  1429→        op,
  1430→        pc: this.pc,
  1431→        stack_depth: this.stack.length,
  1432→        detail,
  1433→      },
  1434→    };
