  1444→  executeCallback(callbackId: number, _args?: any[]): VMResult {
  1445→    const bytecode = this.callbackRegistry.get(callbackId);
  1446→    if (!bytecode) {
  1447→      return this.fail(Op.HALT, 1, `callback_not_found:${callbackId}`);
  1448→    }
  1449→
  1450→    // Execute callback bytecode in isolated context
  1451→    const savedStack = this.stack;
  1452→    const savedVars = this.vars;
  1453→    const savedPc = this.pc;
  1454→
  1455→    this.stack = [];
  1456→    this.vars = new Map();
  1457→    this.pc = 0;
  1458→
  1459→    const result = this.run(bytecode);
  1460→
  1461→    this.stack = savedStack;
  1462→    this.vars = savedVars;
  1463→    this.pc = savedPc;
  1464→
  1465→    return result;
  1466→  }
