     1→/**
     2→ * Function Registry - Manages user-defined function definitions
     3→ * Enables function lookup during IR generation and execution
     4→ */
     5→
     6→export interface FunctionDefinition {
     7→  type: 'FunctionDefinition';
     8→  name: string;
     9→  params: string[];
    10→  body: any; // AST node (Expression or Statement)
    11→  returnType?: string; // Optional return type annotation
    12→  paramTypes?: Record<string, string>; // Optional parameter type annotations
    13→  async?: boolean; // Phase J: async function flag
    14→  annotations?: string[]; // Self-Monitoring Kernel: @monitor 등 어노테이션 목록
    15→}
    16→
    17→export interface FunctionTypes {
    18→  params: Record<string, string>;  // param name -> type
    19→  returnType?: string;             // return type (optional)
    20→}
    21→
    22→export interface FunctionStats {
    23→  totalFunctions: number;
    24→  totalCalls: number;
    25→  callsByFunction: Record<string, number>;
    26→}
    27→
    28→/**
    29→ * FunctionRegistry: Simple Map-based function definition storage
    30→ * O(1) lookup, no global state needed
    31→ * Supports optional type information for each function
    32→ */
    33→export class FunctionRegistry {
    34→  private functions: Map<string, FunctionDefinition> = new Map();
    35→  private callCounts: Map<string, number> = new Map();
    36→  private types: Map<string, FunctionTypes> = new Map();
    37→
    38→  /**
    39→   * Register a function definition
    40→   */
    41→  register(definition: FunctionDefinition): void {
    42→    this.functions.set(definition.name, definition);
    43→    if (!this.callCounts.has(definition.name)) {
    44→      this.callCounts.set(definition.name, 0);
    45→    }
    46→  }
    47→
    48→  /**
    49→   * Look up a function by name
    50→   */
    51→  lookup(name: string): FunctionDefinition | null {
    52→    return this.functions.get(name) || null;
    53→  }
    54→
    55→  /**
    56→   * Check if function exists
    57→   */
    58→  exists(name: string): boolean {
    59→    return this.functions.has(name);
    60→  }
    61→
    62→  /**
    63→   * Get number of registered functions
    64→   */
    65→  count(): number {
    66→    return this.functions.size;
    67→  }
    68→
    69→  /**
    70→   * Get all function names
    71→   */
    72→  getNames(): string[] {
    73→    return Array.from(this.functions.keys());
    74→  }
    75→
    76→  /**
    77→   * Clear all functions
    78→   */
    79→  clear(): void {
    80→    this.functions.clear();
    81→    this.callCounts.clear();
    82→    this.types.clear();
    83→  }
    84→
    85→  /**
    86→   * Track a function call
    87→   */
    88→  trackCall(name: string): void {
    89→    const current = this.callCounts.get(name) || 0;
    90→    this.callCounts.set(name, current + 1);
    91→  }
    92→
    93→  /**
    94→   * Get statistics about function calls
    95→   */
    96→  getStats(): FunctionStats {
    97→    let totalCalls = 0;
    98→    const callsByFunction: Record<string, number> = {};
    99→
   100→    for (const [name, count] of this.callCounts) {
   101→      callsByFunction[name] = count;
   102→      totalCalls += count;
   103→    }
   104→
   105→    return {
   106→      totalFunctions: this.functions.size,
   107→      totalCalls,
   108→      callsByFunction
   109→    };
   110→  }
   111→
   112→  /**
   113→   * Reset call counts (for testing)
   114→   */
   115→  resetCallCounts(): void {
   116→    this.callCounts.clear();
   117→    for (const name of this.functions.keys()) {
   118→      this.callCounts.set(name, 0);
   119→    }
   120→  }
   121→
   122→  /**
   123→   * Store type information for a function
   124→   */
   125→  registerTypes(name: string, types: FunctionTypes): void {
   126→    this.types.set(name, types);
   127→  }
   128→
   129→  /**
   130→   * Get type information for a function
   131→   */
   132→  getTypes(name: string): FunctionTypes | null {
   133→    return this.types.get(name) || null;
   134→  }
   135→
   136→  /**
   137→   * Check if function has type information
   138→   */
   139→  hasTypes(name: string): boolean {
   140→    return this.types.has(name);
   141→  }
   142→
   143→  /**
   144→   * Get function signature string
   145→   * Example: "fn add(a: number, b: number): number"
   146→   */
   147→  getSignature(name: string): string {
   148→    const fn = this.lookup(name);
   149→    if (!fn) return '';
