### 4. IR 컴파일러 - `src/codegen/ir-generator.ts`

**파일**: `/data/data/com.termux/files/home/v2-freelang-ai/src/codegen/ir-generator.ts`

```typescript
// Line 599-601: Lambda case in traverse()
case 'lambda':
  this.generateLambdaIR(node, out);
  break;

// Line 1514-1545: generateLambdaIR() 구현
private generateLambdaIR(lambda: any, out: Inst[]): void {
  // 1. 새 lambda 객체 생성
  out.push({ op: Op.LAMBDA_NEW });

  // 2. 캡처 변수 로드 + 캡처 (capturedVars가 비어있으면 생략)
  if (lambda.capturedVars && lambda.capturedVars.length > 0) {
    for (const varName of lambda.capturedVars) {
      out.push({ op: Op.LOAD, arg: varName });
      out.push({ op: Op.LAMBDA_CAPTURE, arg: varName });
    }
  }

  // 3. body를 sub-instruction으로 저장
  const bodyInstructions: Inst[] = [];
  this.traverse(lambda.body, bodyInstructions);
  const paramNames = lambda.params?.map((p: any) => typeof p === 'string' ? p : (p.name || '')) || [];

  out.push({
    op: Op.LAMBDA_SET_BODY,
    arg: lambda.params.length,
    sub: bodyInstructions,
    params: paramNames
  });
}
```

**핵심 문제**: `capturedVars`가 빈 배열(`[]`)이면 `LAMBDA_CAPTURE` opcode가 전혀 생성되지 않음. 타입 체커 → AST 전파 단계가 누락되어 캡처가 실질적으로 작동하지 않음.

